mapper.select:
SELECT   WHERE c.tenant_id=#{tenant} AND c.member_id=#{member} AND c.coupon_id>#{after}
    AND (LOCATE(#{filter.q},c.coupon_id)>0 OR LOCATE(#{filter.q},d.definition_id)>0 OR LOCATE(#{filter.q},d.name)>0)
    AND CASE WHEN c.status='AVAILABLE' AND c.valid_to<=CURRENT_TIMESTAMP(3) THEN 'EXPIRED' ELSE c.status END=#{filter.status} ORDER BY c.coupon_id LIMIT #{limit}
